/// (gh-1630 F2 second tier) — never speculatively.
const deadPermissions = {
  'contentSettings',
  'downloads',
  'fontSettings',
  'identity',
  'desktopCapture',
};

/// Engines gh-1630 F1 requires vendored into the package.
const requiredVendoredEngines = {
  'quickjs',
  'pyodide',
  'sqljs',
  'webllm',
  'transformers',
  'litert',
};

