Future<Map<String, dynamic>> bridgeCall(
  HeadlessChrome chrome,
  String path,
  List<Object?> args,
) async =>
    (await evaluateInServiceWorker(
          chrome,
          'globalThis.faAgentV2.bridgeCall(${jsonEncode(path)}, '
          '${jsonEncode(args)})',
          awaitPromise: true,
        ))!
        as Map<String, dynamic>;

HeadlessChrome? _chrome;

