        as Map<String, dynamic>;

/// `faAgentV2.bridgeCall(path, args)` → the raw envelope.
Future<Map<String, dynamic>> bridgeCall(
  HeadlessChrome chrome,
  String path,
  List<Object?> args,
) async =>
