    expect((detail['events'] as List), contains('onUpdated'));
  });

  test(
    'AC3: read path end-to-end — chrome.idle.queryState (no curated tool)',
    () async {
      final envelope = await bridgeCall(chrome, 'idle.queryState', [60]);
      expect(
        envelope['ok'],
