Set<String> _manifestPermissions([String? extensionPath]) {
  final source = File(
    '${extensionPath ?? _repoRoot()}/browser_ext/manifest.json',
  ).readAsStringSync();
  final json = source.replaceAll(RegExp(r'^\s*//.*$', multiLine: true), '');
