/// A chrome.downloads entry.
final class DownloadItem {
  const DownloadItem({
    required this.id,
    required this.url,
    required this.filename,
    required this.state,
    required this.paused,
  });

  final int id;
  final String url;
  final String filename;
  final String state; // 'in_progress' | 'complete' | 'interrupted'
  final bool paused;

  Map<String, Object?> toJson() => {
    'id': id,
    'url': url,
    'filename': filename,
    'state': state,
    'paused': paused,
