final class BrowserApiToolSurface {
  BrowserApiToolSurface(
    this._chrome, {
    this.resultBudget = defaultResultBudgetBytes,
    this.pageClassifier = urlHeuristicClassifier,
    this.visitedOrigins,
    this.exfilApproval,
  });

  final ChromeApi _chrome;

  /// The facade this surface drives (hosts re-read permissions through it
  /// when re-applying the second-tier gate).
  ChromeApi get chrome => _chrome;

  /// Serialized-bytes budget per injected frame result (E4).
  final int resultBudget;

  /// Page classifier consulted before every inject_js / cdp_eval run.
  final PageClassifier pageClassifier;

  /// Origins the user actually visited; null = exfil gate off.
  final Set<String>? visitedOrigins;

  /// Host-provided ask for outbound actions the gate flags (cross_origin,
  /// data_exit, …): resolves true when the user (or the approval mode)
  /// authorizes the call — the tool then proceeds. Null keeps the old
  /// hard-error behavior (the conservative backstop for bare surfaces).
  /// The host seeds [visitedOrigins] on allow, so the ask is once per
  /// origin, not once per call.
  final ExfilApprovalAsk? exfilApproval;

  final InjectionValidator _injection = const InjectionValidator();
  final ExfilGate _exfilGate = const ExfilGate();

  /// Masks planted page secrets in page-derived READ results. Heuristic
  /// layers only — no registered secrets at this layer.
  final RedactionPipeline _redactor = RedactionPipeline(
    registeredSecrets: const [],
  );

  static final Map<String, BrowserToolSpec> _specsByName = {
    for (final s in browserApiToolSpecs()) s.name: s,
  };

  /// Spec metadata for one registered tool name. Tools are built from
  /// this table, so the lookup always succeeds for a built tool.
  static BrowserToolSpec specOf(String name) => _specsByName[name]!;

  /// Builds the whole family (39 tools: 34 core + 5 Settings-gated),
  /// names matching [browserApiToolSpecs] exactly.
====
/// [browserApiToolSpecs] entries — one registration path for every host.
/// [visitedOrigins] passes through to the surface constructor: the exfil
/// gate reads the LIVE set at every outbound call, so hosts keep mutating
/// their own set after registration (SW wiring seeds it from tabs +
/// webNavigation). Returns the surface so hosts can keep calling
/// [syncSecondTierTools] when settings or permissions change.
Future<BrowserApiToolSurface> registerBrowserApiTools(
  ToolRegistry registry,
  ChromeApi chrome, {
  Set<String>? visitedOrigins,
  Set<String> enabledSecondTier = const {},
  ExfilApprovalAsk? exfilApproval,
}) async {
  final surface = BrowserApiToolSurface(
    chrome,
    visitedOrigins: visitedOrigins,
    exfilApproval: exfilApproval,
  );
  final tools = surface.tools();
  registry.registerAll([
    for (final tool in tools)
      if (BrowserApiToolSurface.specOf(tool.name).visibility ==
          BrowserToolVisibility.core)
        tool,
  ]);
  await syncSecondTierTools(registry, surface, enabledSecondTier);
  return surface;
}

