TypeMatcher<BrowserApiToolException> _errMsg(String code, Object message) =>
    _err(code).having((e) => e.message, 'message', message);

Object? _validArg(String prop, String type) {
  if (prop == 'world') return 'ISOLATED';
  return switch (type) {
    'string' => 'x',
    'integer' => 1,
    'boolean' => true,
    'array' => [1],
    _ => null,
  };
}

