      final probed = <String>[];
      final (reg2, c2) = dlReg((url) async => probed.add(url), () => 1024);
      // Complete the download as soon as it starts (the tool polls).
      c2.onDownloadStarted = (id) => c2.completeDownload(id, fileSize: 1024);
