    name: name,
    label: name,
    description: description,
    tier: spec.tier,
    parameters: {
      'type': 'object',
      'properties': properties,
      'required': required,
    },
    execute: (arguments, cancelToken, onUpdate) async {
      cancelToken?.throwIfCancelled();
      try {
