      final (reg2, c2) = dlReg(null);
      c2.onDownloadStarted = (id) => c2.completeDownload(id, fileSize: 1);
      for (final pair in const {
        '../../../etc/passwd': 'passwd',
        '..\\..\\evil.exe': 'evil.exe',
        're\x00port.pdf': 'report.pdf',
        '/abs/path/x.txt': 'x.txt',
