  if (size > defaultMaxDownloadBytes) {
    throw BrowserApiToolException('download_too_large',
        '$url is $size bytes — over the ${defaultMaxDownloadBytes}-byte '
        'download cap (maxDownloadBytes)');
  }
  return 'content-length $size';
}
