    throw StateError('tool "$name" has no BrowserToolSpec entry');
  }
  return AgentTool(
    name: name,
    label: name,
    description: description,
    tier: spec.tier,
    parameters: {
      'type': 'object',
      'properties': properties,
      'required': required,
    },
