  // the newer contract; AC2's both-ways catalog check below proves the
  // namespaces never materialized from them).
  const tier1 = {
    'browsingData',
    'clipboardRead',
    'clipboardWrite',
    'declarativeNetRequest',
    'privacy',
    'readingList',
    'search',
    'tabGroups',
    'tts',
    'webRequest',
  };
  const tier2 = {'nativeMessaging', 'proxy', 'tabCapture', 'management'};
  expect(
    declared.containsAll(tier1),
    isTrue,
    reason: 'missing Tier-1: ${tier1.difference(declared)}',
  );
  expect(
    declared.containsAll(tier2),
    isTrue,
    reason: 'missing Tier-2: ${tier2.difference(declared)}',

