/** The hub runner subprocess + its JSON-lines event feed. */
class HubProc {
  private constructor(
    private proc: ChildProcess,
    readonly url: string,
    readonly events: HubEvent[],
  ) {}

  static async start(secret?: string): Promise<HubProc> {
    // A non-empty secret stands the hub up PASSWORD-PROTECTED: upgrades
    // without the credential get 401 before the websocket exists.
    const proc = spawn('dart', ['run', 'browser_ext/e2e/hub_server.dart'], {
      cwd: repoRoot,
      env: secret ? { ...process.env, DAP_E2E_HUB_SECRET: secret } : process.env,
      stdio: ['pipe', 'pipe', 'inherit'],
    });
    const events: HubEvent[] = [];
    const { promise, resolve, reject } = Promise.withResolvers<HubProc>();
    let buffer = '';
    let ready = false;
    proc.stdout!.on('data', (chunk: Buffer) => {
      buffer += chunk.toString('utf8');
      for (;;) {
        const nl = buffer.indexOf('\n');
        if (nl < 0) break;
        const line = buffer.slice(0, nl).trim();
        buffer = buffer.slice(nl + 1);
        if (!line) continue;
        try {
          const event = JSON.parse(line) as HubEvent;
          events.push(event);
          if (!ready && event.type === 'ready' && event.url) {
            ready = true;
            resolve(new HubProc(proc, event.url, events));
          }
        } catch {
          // Build-hook noise on stdout is ignored; JSON lines are ours.
          // gh-1630 rework: a whole-line ignore also ATE relayed events
          // when dart-run noise interleaved into the same chunk (the hub
          // cursor never replays, so the spec's relay bookkeeping silently
          // lost the ext→CLI reply and the DM spec went red — CI run
          // 38969820857). Salvage a noise-prefixed JSON object and warn
          // loudly when a line is still unparseable — never silent.
          const brace = line.indexOf('{');
          const salvaged = brace > 0 ? line.slice(brace) : '';
          const event = salvaged ? safeParse(salvaged) : null;
          if (event) {
            events.push(event);
            if (!ready && event.type === 'ready' && event.url) {
              ready = true;
              resolve(new HubProc(proc, event.url, events));

