  'tabs', 'windows', 'tabGroups', 'sessions', 'history', 'bookmarks',
  'downloads', 'alarms', 'notifications', 'action', 'offscreen',
  'power', 'idle', 'contextMenus', 'omnibox', 'commands', 'webNavigation',
  'system', 'sidePanel', 'identity', 'readingList', 'search', 'tts',
